-- Generated by build_muvna_import.py. Run AFTER 20261012010000_accessories_catalog.sql.
-- Only retail prices; KZT assumed from Sketo context, verify before publishing.
-- All products are DRAFT. No photos, wholesale prices or unrecognised SKUs inserted.
-- Exact rerun is a no-op: it cannot reset later edits, prices or inventory.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('sketo-muvna-20261012'));
DO $import$
DECLARE
  payload jsonb := $muvna$
__PAYLOAD__
$muvna$::jsonb;
  batch_key constant text := 'muvna-pdf-20261012-v1';
  source_hash constant text := '__SHA256__';
  prior public.accessory_import_batches%ROWTYPE;
  item jsonb;
  variant jsonb;
  product_uuid uuid;
  variant_uuid uuid;
BEGIN
  SELECT * INTO prior FROM public.accessory_import_batches WHERE import_key = batch_key;
  IF FOUND THEN
    IF prior.source_sha256 <> source_hash OR prior.payload_md5 <> md5(payload::text) THEN
      RAISE EXCEPTION 'Import key already exists with different content. Prepare a reviewed follow-up migration.';
    END IF;
    RAISE NOTICE 'MUVNA import already applied; preserving all current catalog edits and stock.';
    RETURN;
  END IF;

  IF jsonb_array_length(payload) <> __PRODUCT_COUNT__ OR
     (SELECT count(*) FROM jsonb_array_elements(payload) p CROSS JOIN LATERAL jsonb_array_elements(p->'variants')) <> __VARIANT_COUNT__ THEN
    RAISE EXCEPTION 'Unexpected import counts';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(payload) p
             JOIN public.accessory_products existing ON existing.slug = p->>'slug') OR
     EXISTS (SELECT 1 FROM jsonb_array_elements(payload) p
             CROSS JOIN LATERAL jsonb_array_elements(p->'variants') v
             JOIN public.accessory_variants existing ON existing.sku = v->>'sku') THEN
    RAISE EXCEPTION 'A source slug/SKU already exists outside this import. Resolve collision before import; no existing rows overwritten.';
  END IF;

  INSERT INTO public.accessory_import_batches
    (import_key, source_file, source_sha256, payload_md5, product_count, variant_count)
  VALUES (batch_key, 'Muvna.pdf', source_hash, md5(payload::text), __PRODUCT_COUNT__, __VARIANT_COUNT__);

  FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
    IF (SELECT count(DISTINCT (v->>'retail_price')) FROM jsonb_array_elements(item->'variants') v) <> 1 THEN
      RAISE EXCEPTION 'Mixed prices in colour group %', item->>'slug';
    END IF;
    INSERT INTO public.accessory_products (slug,brand,category,name,attributes,editorial_state,sort_order)
    VALUES (item->>'slug','muvna',item->>'category',item->>'name',item->'attributes','draft',(item->>'sort_order')::integer)
    RETURNING id INTO product_uuid;
    INSERT INTO public.accessory_translations (product_id,locale,name,description)
    VALUES (product_uuid,'ru',item->>'name',item->>'description');
    FOR variant IN SELECT value FROM jsonb_array_elements(item->'variants') LOOP
      INSERT INTO public.accessory_variants
        (product_id,sku,color_code,color_label,retail_price,currency,stock_quantity,sort_order)
      VALUES (product_uuid,variant->>'sku',variant->>'color_code',variant->>'color_label',
        (variant->>'retail_price')::numeric,'KZT',(variant->>'stock_quantity')::integer,(variant->>'sort_order')::integer)
      RETURNING id INTO variant_uuid;
      INSERT INTO public.accessory_import_rows (variant_id,import_key,source_page,source_row,source_name)
      VALUES (variant_uuid,batch_key,(variant->>'source_page')::integer,(variant->>'source_row')::integer,variant->>'source_name');
    END LOOP;
  END LOOP;
END;
$import$;
COMMIT;

SELECT p.id,p.slug,p.name,p.editorial_state,count(v.id) AS colours,min(v.retail_price) AS retail_price
FROM public.accessory_products p JOIN public.accessory_variants v ON v.product_id=p.id
JOIN public.accessory_import_rows r ON r.variant_id=v.id
WHERE r.import_key='muvna-pdf-20261012-v1'
GROUP BY p.id ORDER BY p.sort_order;
